/**
 * IVX Owner System API Client
 *
 * Shared helper for calling the platform extensions API endpoints
 * (Points 5-8: owner system, compliance, payments, global core, pilot markets).
 */

import { supabase } from '@/lib/supabase';
import { getDirectApiBaseUrl } from '@/lib/api-base';

export async function getAuth Token(): Promise<string | null> {
  const { data: { session } } = await supabase.auth.getSession();
  return session?.access_token ?? null;
}

export async function fetchOwnerApi<T>(
  path: string,
  options: RequestInit = {},
): Promise<T> {
  const token = await getAuthToken();
  const base = getDirectApiBaseUrl();

  const res = await fetch(`${base}${path}`, {
    ...options,
    headers: {
      'Content-Type': 'application/json',
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...options.headers,
    },
  });

  const data = await res.json().catch(() => null) as T | null;
  if (!res.ok) {
    throw new Error(
      (data as { error?: string })?.error || `API error: ${res.status}`,
    );
  }
  return data as T;
}

// ---- Type definitions ----

export interface OwnerProfile {
  id: string;
  user_id: string;
  display_name: string;
  legal_name: string | null;
  entity_type: string;
  kyc_status: string;
  kyb_status: string;
  sanctions_status: string;
  accreditation_status: string;
  risk_rating: string;
  total_holdings_value: number;
  total_equity: number;
  total_annual_income: number;
  total_annual_expenses: number;
  total_properties: number;
  is_verified: boolean;
  preferred_currency: string;
  preferred_language: string;
}

export interface OwnerHolding {
  id: string;
  property_title: string;
  acquisition_date: string;
  acquisition_price: number;
  currency_code: string;
  current_value: number;
  outstanding_mortgage: number;
  equity: number;
  ownership_percentage: number;
  annual_rental_income: number;
  annual_expenses: number;
  annual_net_cash_flow: number;
  cap_rate: number | null;
  cash_on_cash_return: number | null;
  status: string;
  is_listed_for_sale: boolean;
  notes: string | null;
}

export interface IncomeExpenseEntry {
  id: string;
  entry_type: 'income' | 'expense';
  category: string;
  description: string | null;
  amount: number;
  currency_code: string;
  entry_date: string;
  recurring: boolean;
}

export interface OwnerDocument {
