          )}
        </View>
      </View>
      <View style={styles.recordRight}>
        <Text style={[styles.recordAmount, { color: isPositive ? Colors.text : Colors.error }]}>
          {isPositive ? '+' : '-'}{formatCurrencyWithDecimals(record.amount)}
        </Text>
        {record.fee_amount > 0 && (
          <Text style={styles.recordFee}>
