            />
            <ModalInput
              label="Current Value"
              value={currentValue}
              onChange={setCurrentValue}
              placeholder="550000"
              keyboardType="numeric"
            />
            <ModalInput
              label="Outstanding Mortgage"
              value={outstandingMortgage}
